// src/pages/BillDetail.js
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { billApi } from '../utils/api';
import { useApp } from '../Context/AppContext';

var statusColor = function (s) {
  if (s === 'paid')      return '#00D9A3';
  if (s === 'draft')     return '#FFB800';
  if (s === 'cancelled') return '#FF4D6A';
  return '#6E6B8A';
};

var catColors = {
  entrance: '#00B4FF',
  donation: '#FF4D6A',
  selling:  '#00D9A3',
  custom:   '#6E6B8A',
};

var Row = function ({ label, value, mono, highlight }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '0.5rem 0', borderBottom: '1px solid var(--border-1)' }}>
      <span style={{ fontSize: '0.82rem', color: 'var(--text-3)' }}>{label}</span>
      <span style={{
        fontFamily: mono ? 'var(--mono)' : 'var(--font)',
        fontWeight: highlight ? '800' : '600',
        color: highlight ? 'var(--orange)' : 'var(--text-1)',
        fontSize: highlight ? '1.1rem' : '0.88rem',
      }}>{value}</span>
    </div>
  );
};

// ─── Inject print CSS once ────────────────────────────────────────────────────
var PRINT_CSS = `
@media print {
  @page { margin: 12mm; size: A4; }
  body > * { display: none !important; }
  #bill-printable { display: block !important; position: static !important; }
}
`;

var PrintableBill = function ({ bill }) {
  var sc = statusColor(bill.status);
  return (
    <div id="bill-printable" style={{ display: 'bill-printable', fontFamily: "'Segoe UI', Arial, sans-serif", color: '#111', background: 'white' }}>
      <style>{PRINT_CSS}</style>

      {/* ── Header ── */}
      <div style={{ background: 'linear-gradient(135deg,#FF6B35,#F7931E)', color: 'white', padding: '22px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div>
          <div style={{ fontSize: '24px', fontWeight: '900' }}>⚡ BillGen</div>
          <div style={{ fontSize: '11px', opacity: 0.85 }}>Multi-Catalog Billing System</div>
        </div>
        <div style={{ textAlign: 'right' }}>
          <div style={{ fontSize: '18px', fontWeight: '800' }}>{bill.invoiceNumber}</div>
          <div style={{ marginTop: '5px', display: 'inline-block', padding: '2px 12px', borderRadius: '999px', background: 'rgba(255,255,255,0.25)', fontSize: '10px', fontWeight: '700', textTransform: 'uppercase', letterSpacing: '1px' }}>
            {bill.status}
          </div>
        </div>
      </div>

      {/* ── Customer / Invoice info ── */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', borderBottom: '2px solid #f0f0f0' }}>
        <div style={{ padding: '18px 30px', borderRight: '1px solid #f0f0f0' }}>
          <div style={{ fontSize: '9px', fontWeight: '700', color: '#FF6B35', textTransform: 'uppercase', letterSpacing: '1px', marginBottom: '8px' }}>Bill To</div>
          <div style={{ fontSize: '15px', fontWeight: '700', marginBottom: '3px' }}>{bill.customerName || 'Walk-in Customer'}</div>
          {bill.customerEmail && <div style={{ fontSize: '12px', color: '#555' }}>{bill.customerEmail}</div>}
          {bill.customerPhone && <div style={{ fontSize: '12px', color: '#555' }}>{bill.customerPhone}</div>}
        </div>
        <div style={{ padding: '18px 30px' }}>
          <div style={{ fontSize: '9px', fontWeight: '700', color: '#FF6B35', textTransform: 'uppercase', letterSpacing: '1px', marginBottom: '8px' }}>Invoice Details</div>
          {[
            { l: 'Invoice #', v: bill.invoiceNumber },
            { l: 'Date',      v: new Date(bill.createdAt).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }) },
            { l: 'Status',    v: bill.status.toUpperCase() },
          ].map(function (r) {
            return (
              <div key={r.l} style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '4px' }}>
                <span style={{ fontSize: '12px', color: '#888' }}>{r.l}</span>
                <span style={{ fontSize: '12px', fontWeight: '700' }}>{r.v}</span>
              </div>
            );
          })}
        </div>
      </div>

      {/* ── Items ── */}
      <div style={{ padding: '22px 30px' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '20px' }}>
          <thead>
            <tr style={{ background: '#FFF5F0' }}>
              {[['#','center'],['Item','left'],['Category','left'],['Unit Price','right'],['Qty','center'],['Total','right']].map(function (h) {
                return <th key={h[0]} style={{ padding: '9px 10px', textAlign: h[1], fontSize: '9px', fontWeight: '700', color: '#FF6B35', textTransform: 'uppercase', letterSpacing: '0.8px', borderBottom: '2px solid #FFE0D0' }}>{h[0]}</th>;
              })}
            </tr>
          </thead>
          <tbody>
            {bill.items.map(function (item, idx) {
              var cc = catColors[item.category] || '#6E6B8A';
              return (
                <tr key={item.id} style={{ borderBottom: '1px solid #f5f5f5', background: idx % 2 === 0 ? 'white' : '#FAFAFA' }}>
                  <td style={{ padding: '9px 10px', textAlign: 'center', fontSize: '11px', color: '#999' }}>{idx + 1}</td>
                  <td style={{ padding: '9px 10px', fontSize: '12px', fontWeight: '600' }}>{item.name}</td>
                  <td style={{ padding: '9px 10px' }}>
                    <span style={{ fontSize: '9px', padding: '2px 7px', borderRadius: '999px', background: cc + '22', border: '1px solid ' + cc + '55', color: cc, fontWeight: '700', textTransform: 'uppercase' }}>
                      {item.category}
                    </span>
                  </td>
                  <td style={{ padding: '9px 10px', textAlign: 'right', fontSize: '12px', fontFamily: 'monospace' }}>${item.price.toFixed(2)}</td>
                  <td style={{ padding: '9px 10px', textAlign: 'center', fontSize: '12px' }}>{item.quantity}</td>
                  <td style={{ padding: '9px 10px', textAlign: 'right', fontSize: '12px', fontWeight: '700', color: '#FF6B35', fontFamily: 'monospace' }}>${item.total.toFixed(2)}</td>
                </tr>
              );
            })}
          </tbody>
        </table>

        {/* Totals */}
        <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
          <div style={{ minWidth: '260px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', padding: '5px 0', borderBottom: '1px solid #f0f0f0' }}>
              <span style={{ fontSize: '12px', color: '#666' }}>Subtotal</span>
              <span style={{ fontSize: '12px', fontFamily: 'monospace' }}>${bill.subtotal.toFixed(2)}</span>
            </div>
            {bill.discountType !== 'none' && bill.discountAmount > 0 && (
              <div style={{ display: 'flex', justifyContent: 'space-between', padding: '5px 0', borderBottom: '1px solid #f0f0f0' }}>
                <span style={{ fontSize: '12px', color: '#00D9A3' }}>Discount ({bill.discountType === 'percentage' ? bill.discountValue + '%' : 'Fixed'})</span>
                <span style={{ fontSize: '12px', fontFamily: 'monospace', color: '#00D9A3' }}>−${bill.discountAmount.toFixed(2)}</span>
              </div>
            )}
            <div style={{ display: 'flex', justifyContent: 'space-between', padding: '5px 0', borderBottom: '1px solid #f0f0f0' }}>
              <span style={{ fontSize: '12px', color: '#666' }}>Tax ({bill.taxRate}%)</span>
              <span style={{ fontSize: '12px', fontFamily: 'monospace' }}>${bill.taxAmount.toFixed(2)}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', padding: '11px 14px', marginTop: '8px', background: 'linear-gradient(135deg,#FF6B35,#F7931E)', borderRadius: '8px' }}>
              <span style={{ fontSize: '14px', fontWeight: '800', color: 'white' }}>TOTAL</span>
              <span style={{ fontSize: '16px', fontWeight: '900', color: 'white', fontFamily: 'monospace' }}>${bill.total.toFixed(2)}</span>
            </div>
          </div>
        </div>

        {bill.notes && (
          <div style={{ marginTop: '20px', padding: '12px 16px', background: '#FFF8F5', borderLeft: '4px solid #FF6B35', borderRadius: '0 6px 6px 0' }}>
            <div style={{ fontSize: '9px', fontWeight: '700', color: '#FF6B35', textTransform: 'uppercase', letterSpacing: '1px', marginBottom: '4px' }}>Notes</div>
            <div style={{ fontSize: '12px', color: '#555' }}>{bill.notes}</div>
          </div>
        )}

        <div style={{ marginTop: '28px', textAlign: 'center', borderTop: '1px solid #f0f0f0', paddingTop: '12px', fontSize: '11px', color: '#bbb' }}>
          Generated by BillGen — Printed on {new Date().toLocaleString()}
        </div>
      </div>
    </div>
  );
};

// ─── Main BillDetail ──────────────────────────────────────────────────────────
var BillDetail = function () {
  var { id }   = useParams();
  var navigate = useNavigate();
  var app      = useApp();

  var [bill, setBill]         = useState(null);
  var [loading, setLoading]   = useState(true);
  var [updating, setUpdating] = useState(false);

  useEffect(function () {
    billApi.getById(id)
      .then(function (res) { setBill(res.data.data); })
      .catch(function (err) { app.addToast(err.message, 'danger'); navigate('/bills'); })
      .finally(function () { setLoading(false); });
  }, [id]);

  var handleStatusChange = async function (newStatus) {
    setUpdating(true);
    try {
      var res = await billApi.setStatus(id, newStatus);
      setBill(res.data.data);
      app.addToast('Status updated to ' + newStatus, 'success');
    } catch (err) { app.addToast(err.message, 'danger'); }
    finally { setUpdating(false); }
  };

  var handleDelete = async function () {
    if (!window.confirm('Permanently delete this bill?')) return;
    try {
      await billApi.remove(id);
      app.addToast('Bill deleted', 'success');
      navigate('/bills');
    } catch (err) { app.addToast(err.message, 'danger'); }
  };

  var handlePrint = function () {
    var el = document.getElementById('bill-printable');
    if (el) {
      el.style.display = 'block';
      window.print();
      setTimeout(function () { el.style.display = 'none'; }, 800);
    }
  };

  if (loading) {
    return (
      <div className="loading-center" style={{ height: '60vh' }}>
        <span className="spinner-lg spinner" />
        <span style={{ color: 'var(--text-3)' }}>Loading bill...</span>
      </div>
    );
  }
  if (!bill) return null;

  var sc = statusColor(bill.status);
  var cc = function (cat) { return catColors[cat] || 'var(--text-3)'; };

  return (
    <div>
      {/* Hidden printable invoice */}
      <PrintableBill bill={bill} />

      {/* ── Header bar ── */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1.5rem', flexWrap: 'wrap', gap: '0.75rem' }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '6px' }}>
            <Link to="/bills" style={{ color: 'var(--text-3)', fontSize: '0.82rem' }}>All Bills</Link>
            <span style={{ color: 'var(--text-4)' }}>›</span>
            <span style={{ color: 'var(--text-2)', fontSize: '0.82rem' }}>{bill.invoiceNumber}</span>
          </div>
          <h1 style={{ fontSize: '1.4rem', fontWeight: '800' }}>
            {bill.invoiceNumber}
            <span style={{ marginLeft: '0.75rem', fontSize: '0.7rem', padding: '3px 12px', borderRadius: 'var(--r-full)', background: sc + '22', border: '1px solid ' + sc + '44', color: sc, fontWeight: '700', textTransform: 'uppercase', letterSpacing: '0.1em', verticalAlign: 'middle' }}>
              {bill.status}
            </span>
          </h1>
        </div>

        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
          <button className="btn btn-primary btn-sm" onClick={handlePrint} style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            🖨️ Print / PDF
          </button>
          {bill.status !== 'paid' && (
            <button className="btn btn-success btn-sm" onClick={function () { return handleStatusChange('paid'); }} disabled={updating}>✓ Mark Paid</button>
          )}
          {bill.status !== 'cancelled' && (
            <button className="btn btn-ghost btn-sm" onClick={function () { return handleStatusChange('cancelled'); }} disabled={updating} style={{ color: 'var(--rose)', borderColor: 'var(--rose)' }}>✕ Cancel</button>
          )}
          <Link to={'/bills/' + id + '/edit'} className="btn btn-secondary btn-sm">✏️ Edit</Link>
          <button className="btn btn-ghost btn-sm" onClick={handleDelete} style={{ color: 'var(--rose)' }}>🗑 Delete</button>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 340px', gap: '1.25rem', alignItems: 'start' }}>
        <div>
          {/* Customer */}
          <div className="card" style={{ marginBottom: '1.25rem' }}>
            <h2 style={{ fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: '1rem' }}>Customer Details</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))', gap: '0.75rem' }}>
              {[{ label: 'Name', value: bill.customerName || '—' }, { label: 'Email', value: bill.customerEmail || '—' }, { label: 'Phone', value: bill.customerPhone || '—' }].map(function (f) {
                return (
                  <div key={f.label}>
                    <div style={{ fontSize: '0.65rem', color: 'var(--text-4)', textTransform: 'uppercase', letterSpacing: '0.1em', fontWeight: '700', marginBottom: '3px' }}>{f.label}</div>
                    <div style={{ fontSize: '0.88rem', color: 'var(--text-1)', fontWeight: '600' }}>{f.value}</div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Items */}
          <div className="card" style={{ padding: 0, overflow: 'hidden', marginBottom: '1.25rem' }}>
            <div style={{ padding: '1rem 1.25rem', borderBottom: '1px solid var(--border-1)' }}>
              <h2 style={{ fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.07em' }}>Line Items ({bill.items.length})</h2>
            </div>
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead>
                <tr style={{ background: 'rgba(255,107,53,0.05)', borderBottom: '1px solid var(--border-1)' }}>
                  {['Item', 'Category', 'Unit Price', 'Qty', 'Total'].map(function (h) {
                    return <th key={h} style={{ padding: '0.6rem 1rem', textAlign: 'left', fontSize: '0.65rem', fontWeight: '700', color: 'var(--text-3)', textTransform: 'uppercase', letterSpacing: '0.1em' }}>{h}</th>;
                  })}
                </tr>
              </thead>
              <tbody>
                {bill.items.map(function (item) {
                  return (
                    <tr key={item.id} style={{ borderBottom: '1px solid var(--border-1)' }}>
                      <td style={{ padding: '0.75rem 1rem', fontWeight: '600', fontSize: '0.88rem' }}>{item.name}</td>
                      <td style={{ padding: '0.75rem 1rem' }}>
                        <span style={{ fontSize: '0.65rem', padding: '2px 8px', borderRadius: 'var(--r-full)', background: cc(item.category) + '22', border: '1px solid ' + cc(item.category) + '44', color: cc(item.category), fontWeight: '700', textTransform: 'uppercase', letterSpacing: '0.08em' }}>{item.category}</span>
                      </td>
                      <td style={{ padding: '0.75rem 1rem', fontFamily: 'var(--mono)', fontSize: '0.85rem', color: 'var(--text-2)' }}>${item.price.toFixed(2)}</td>
                      <td style={{ padding: '0.75rem 1rem', fontSize: '0.85rem', color: 'var(--text-2)', textAlign: 'center' }}>{item.quantity}</td>
                      <td style={{ padding: '0.75rem 1rem', fontFamily: 'var(--mono)', fontWeight: '700', color: 'var(--orange)' }}>${item.total.toFixed(2)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          {bill.notes && (
            <div className="card">
              <h2 style={{ fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: '0.6rem' }}>Notes</h2>
              <p style={{ fontSize: '0.87rem', color: 'var(--text-2)', lineHeight: 1.6 }}>{bill.notes}</p>
            </div>
          )}
        </div>

        {/* Right column */}
        <div>
          {/* Totals */}
          <div className="card" style={{ marginBottom: '1.25rem' }}>
            <h2 style={{ fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: '1rem' }}>Summary</h2>
            <Row label="Subtotal" value={'$' + bill.subtotal.toFixed(2)} mono />
            {bill.discountType !== 'none' && bill.discountAmount > 0 && (
              <div style={{ display: 'flex', justifyContent: 'space-between', padding: '0.5rem 0', borderBottom: '1px solid var(--border-1)' }}>
                <span style={{ fontSize: '0.82rem', color: 'var(--emerald)' }}>Discount ({bill.discountType === 'percentage' ? bill.discountValue + '%' : 'Fixed'})</span>
                <span style={{ fontFamily: 'var(--mono)', fontWeight: '600', color: 'var(--emerald)', fontSize: '0.88rem' }}>−${bill.discountAmount.toFixed(2)}</span>
              </div>
            )}
            <Row label={'Tax (' + bill.taxRate + '%)'} value={'$' + bill.taxAmount.toFixed(2)} mono />
            <Row label="Total" value={'$' + bill.total.toFixed(2)} mono highlight />
          </div>

          {/* Export card */}
          <div className="card" style={{ marginBottom: '1.25rem' }}>
            <h2 style={{ fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: '1rem' }}>
              📤 Export
            </h2>
            <button className="btn btn-primary" onClick={handlePrint} style={{ width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px', marginBottom: '0.6rem' }}>
              🖨️ Print / Save as PDF
            </button>
            <p style={{ fontSize: '0.72rem', color: 'var(--text-4)', margin: 0, lineHeight: 1.6, padding: '0.6rem', background: 'var(--bg-3)', borderRadius: 'var(--r-sm)' }}>
              💡 In the browser print dialog, set <strong style={{ color: 'var(--text-2)' }}>Destination → Save as PDF</strong> to download a clean invoice PDF.
            </p>
          </div>

          {/* Bill info */}
          <div className="card">
            <h2 style={{ fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-2)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: '1rem' }}>Bill Info</h2>
            <Row label="Invoice #" value={bill.invoiceNumber} />
            <Row label="Status"    value={bill.status.charAt(0).toUpperCase() + bill.status.slice(1)} />
            <Row label="Created"   value={new Date(bill.createdAt).toLocaleString()} />
            <Row label="Updated"   value={new Date(bill.updatedAt).toLocaleString()} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default BillDetail;
